let translator=null,translatorLocale='',translateEpoch=0,translationCache=new Map(),originalText=new WeakMap();
function appLocale(){return state.settings.language||'en'}
function languageName(code,native=false){try{return new Intl.DisplayNames([native?code:appLocale()],{type:'language'}).of(code)}catch{return code}}
function languageOptions(selected){return languageCodes.map(c=>`<option value="${c}"${c===selected?' selected':''}>${esc(languageName(c,true))} — ${esc(languageName(c))}</option>`).join('')}
function navLabel(id,fallback){if(id==='advisor')return advisorState().name;let pack=shellLanguages[appLocale()]||shellLanguages.en,idx=shellKeys.indexOf(id);return idx>=0?pack.split('|')[idx]:fallback}
function applyLocale(){let locale=appLocale(),rtl=['ar','he','fa','ur','ps','sd','ug','yi','dv'].includes(locale);document.documentElement.lang=locale;document.documentElement.dir=rtl?'rtl':'ltr';$('#main').lang=translator&&translatorLocale===locale?locale:'en';document.querySelectorAll('#nav [data-page]').forEach(b=>{let item=nav.find(n=>n[0]===b.dataset.page);if(item)b.innerHTML=`<span class="icon" aria-hidden="true">${item[1]}</span>${esc(navLabel(item[0],item[2]))}`});let current=nav.find(n=>n[0]===page);if(current)$('#breadcrumb').textContent=navLabel(current[0],current[2]);let control=$('#languageButton');if(control)control.textContent='◎ '+languageName(locale,true);if(translator&&translatorLocale===locale)translateVisible().catch(()=>{});}
function languages(){let locale=appLocale();return title('INTERNATIONAL BY DESIGN','Your language. Your voice.','Choose a language for navigation and date formatting. Translation coverage is shown honestly; selecting a language does not mean every page is already translated.')+`<section class="card"><label>Language / Idioma / Langue / اللغة / भाषा<select id="siteLanguage">${languageOptions(locale)}</select></label><div class="note"><b>${shellLanguages[locale]?'Bundled navigation available':'English navigation fallback'}</b><span>${Object.keys(shellLanguages).length} navigation languages · ${languageCodes.length} language preferences. Detailed pages and the interest directory remain English until translated. Bundled translations have not had professional linguistic review.</span></div><div class="row wrap"><button id="enableTranslation">Translate page on this device</button><button id="restoreEnglish" class="outline">Restore English</button></div><p id="translationStatus" class="statusline" role="status">Full-page translation requires a compatible browser and language pair. Unsupported browsers keep the original text. No text is sent by this app to a translation server.</p><h3 style="margin-top:25px">Meaning matters</h3><p>Translations of consent, identities and community-specific terms need special care. Keep the original available and confirm meaning in your own words. There is no promise of support for every language or dialect.</p><p><a href="https://developer.chrome.com/docs/ai/translator-api" target="_blank" rel="noopener noreferrer">Browser translation support ↗</a></p></section>`}
async function enableTranslation(){const locale=appLocale(),status=$('#translationStatus');if(locale==='en'){status.textContent='The original interface is already English.';return}if(!('Translator' in globalThis)){status.textContent='On-device page translation is unavailable in this browser. Your selected navigation language still works. Use your browser’s page-translation feature if available.';return}status.textContent='Checking language support…';try{let availability=await Translator.availability({sourceLanguage:'en',targetLanguage:locale});if(availability==='unavailable'){status.textContent='This browser does not support the selected language pair. English page text remains available.';return}translator=await Translator.create({sourceLanguage:'en',targetLanguage:locale,monitor(m){m.addEventListener('downloadprogress',e=>{status.textContent=`Preparing language model: ${Math.round(e.loaded*100)}%`})}});translatorLocale=locale;status.textContent='On-device translation enabled. Machine translations may need correction.';await translateVisible()}catch{status.textContent='Translation could not start. No profile data was changed.'}}
async function translateVisible(){if(!translator)return;const epoch=++translateEpoch,active=translator;const nodes=[],walker=document.createTreeWalker($('#main'),NodeFilter.SHOW_TEXT);let node;document.querySelectorAll('#main option').forEach(o=>{if(!o.hasAttribute('value'))o.value=o.textContent});while(node=walker.nextNode()){if(!node.textContent.trim()||node.parentElement.closest('script,style,textarea,input,[translate="no"],#translationStatus,#siteLanguage'))continue;nodes.push(node)}for(const n of nodes){if(epoch!==translateEpoch||active!==translator)return;let original=originalText.get(n)||n.textContent;originalText.set(n,original);let key=translatorLocale+'|'+original,result=translationCache.get(key);try{if(!result){result=await active.translate(original);translationCache.set(key,result)}if(n.isConnected&&epoch===translateEpoch)n.textContent=result}catch{return}}}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.id==='languageButton')go('languages');if(b.id==='enableTranslation')enableTranslation();if(b.id==='restoreEnglish'){state.settings.language='en';translator?.destroy();translator=null;translatorLocale='';translateEpoch++;persist();render()}});
document.addEventListener('change',e=>{if(e.target.id==='siteLanguage'){state.settings.language=e.target.value;translator?.destroy();translator=null;translatorLocale='';translateEpoch++;persist();render()}});
